//! Multipart image hosting for AI-generated bytes (Imgdrip).

use async_trait::async_trait;
use eyre::{Result, WrapErr as _};
use reqwest::multipart;
use serde::Deserialize;

const DEFAULT_UPLOAD_URL: &str = "https://imgdrip.com/api/upload";

/// Uploads image bytes to a public CDN and returns a shareable URL.
#[async_trait]
pub trait ImageHost: Send + Sync {
    async fn upload(&self, bytes: &[u8], media_type: &str) -> Result<String>;
}

/// Imgdrip multipart uploader (`POST …/api/upload`, field `file`).
pub struct ImgdripHost {
    http: reqwest::Client,
    upload_url: String,
}

impl ImgdripHost {
    pub fn new(http: reqwest::Client) -> Self {
        Self::with_upload_url(http, DEFAULT_UPLOAD_URL.to_string())
    }

    /// Test hook: override upload endpoint (e.g. wiremock).
    pub fn with_upload_url(http: reqwest::Client, upload_url: String) -> Self {
        Self { http, upload_url }
    }
}

#[async_trait]
impl ImageHost for ImgdripHost {
    async fn upload(&self, bytes: &[u8], media_type: &str) -> Result<String> {
        let filename = filename_for_media_type(media_type);
        let part = multipart::Part::bytes(bytes.to_vec())
            .file_name(filename)
            .mime_str(media_type)
            .wrap_err("imgdrip upload: invalid media type")?;
        let form = multipart::Form::new().part("file", part);

        let resp = self
            .http
            .post(&self.upload_url)
            .multipart(form)
            .send()
            .await
            .wrap_err("imgdrip upload: request failed")?
            .error_for_status()
            .wrap_err("imgdrip upload: non-2xx")?;

        let body = resp
            .text()
            .await
            .wrap_err("imgdrip upload: read response body")?;
        parse_upload_url(&body).wrap_err("imgdrip upload: no URL in response")
    }
}

fn filename_for_media_type(media_type: &str) -> &'static str {
    match media_type {
        "image/png" => "image.png",
        "image/jpeg" | "image/jpg" => "image.jpeg",
        "image/webp" => "image.webp",
        _ => "image.png",
    }
}

#[derive(Debug, Deserialize)]
struct UploadResponse {
    image: ImageUrls,
}

#[derive(Debug, Deserialize)]
struct ImageUrls {
    #[serde(default)]
    cdn_url: Option<String>,
    #[serde(default)]
    page_url: Option<String>,
}

fn parse_upload_url(body: &str) -> Result<String> {
    if let Ok(parsed) = serde_json::from_str::<UploadResponse>(body) {
        if let Some(url) = parsed.image.cdn_url.filter(|u| !u.trim().is_empty()) {
            return Ok(url);
        }
        if let Some(url) = parsed.image.page_url.filter(|u| !u.trim().is_empty()) {
            return Ok(url);
        }
    }

    let trimmed = body.trim();
    if trimmed.is_empty() {
        eyre::bail!("empty response body");
    }
    Ok(trimmed.to_string())
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;
    use wiremock::matchers::{method, path};
    use wiremock::{Mock, MockServer, ResponseTemplate};

    #[tokio::test]
    async fn imgdrip_upload_returns_cdn_url() {
        crate::install_crypto_provider();
        let server = MockServer::start().await;
        Mock::given(method("POST"))
            .and(path("/api/upload"))
            .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                "image": {"cdn_url": "https://cdn.example/x.png", "page_url": "https://imgdrip.com/x"}
            })))
            .mount(&server)
            .await;
        let host = ImgdripHost::with_upload_url(
            reqwest::Client::new(),
            format!("{}/api/upload", server.uri()),
        );
        let url = host.upload(b"fakepng", "image/png").await.unwrap();
        assert_eq!(url, "https://cdn.example/x.png");
    }
}
